```rust
//! Byte -> nibble expansion.
//!
//! Every trie key insertion expands its key into one nibble per 4 bits,
//! high nibble first: `[0xab, 0xcd] -> [0x0a, 0x0b, 0x0c, 0x0d]`.

#[cfg(target_arch = "x86_64")]
use std::arch::x86_64::*;

/// Expand each byte of `bytes` into two nibbles, high nibble first.
///
/// Dispatches to an AVX2 implementation when the CPU supports it, falling back
/// to a scalar loop otherwise.
pub fn bytes_to_nibbles(bytes: &[u8]) -> Vec<u8> {
    let len = bytes.len();
    let mut out: Vec<u8> = Vec::with_capacity(len * 2);

    // SAFETY: `out` was just allocated with capacity `len * 2`, so `as_mut_ptr`
    // is valid for that many writes, and `bytes` is valid for `len` reads. The
    // two regions cannot overlap: `out` owns a fresh allocation. `expand` fully
    // initialises all `len * 2` bytes, so `set_len` is sound afterwards.
    unsafe {
        expand(bytes.as_ptr(), len, out.as_mut_ptr());
        out.set_len(len * 2);
    }

    out
}

/// Expand `bytes` into a caller-provided buffer, avoiding the allocation.
///
/// `out` must be exactly `bytes.len() * 2` long. This is the variant to use on
/// hot paths where the key length is known (e.g. a 32-byte account hash can use
/// a `[u8; 64]` stack buffer).
///
/// # Panics
/// Panics if `out.len() != bytes.len() * 2`.
pub fn bytes_to_nibbles_into(bytes: &[u8], out: &mut [u8]) {
    assert_eq!(
        out.len(),
        bytes.len() * 2,
        "nibble buffer must be exactly twice the input length"
    );

    // SAFETY: the assert above guarantees `out` is valid for `bytes.len() * 2`
    // writes, and `bytes` is valid for `bytes.len()` reads. `&[u8]` and
    // `&mut [u8]` cannot alias.
    unsafe { expand(bytes.as_ptr(), bytes.len(), out.as_mut_ptr()) }
}

/// Write `len * 2` nibbles read from `src` into `dst`.
///
/// # Safety
/// `src` must be valid for `len` reads, `dst` must be valid for `len * 2`
/// writes, and the two regions must not overlap.
#[inline]
unsafe fn expand(src: *const u8, len: usize, dst: *mut u8) {
    #[cfg(target_arch = "x86_64")]
    {
        // `is_x86_feature_detected!` caches its result in a static, so this
        // costs a relaxed atomic load plus a predictable branch.
        if is_x86_feature_detected!("avx2") {
            // SAFETY: AVX2 support just confirmed; pointer contract forwarded
            // from this function's own safety requirements.
            return unsafe { expand_avx2(src, len, dst) };
        }
    }

    // SAFETY: pointer contract forwarded from this function's requirements.
    unsafe { expand_scalar(src, len, dst) }
}

/// # Safety
/// Same contract as [`expand`].
#[inline]
unsafe fn expand_scalar(src: *const u8, len: usize, dst: *mut u8) {
    for i in 0..len {
        // SAFETY: `i < len`, so `src.add(i)` and `dst.add(i * 2 + 1)` are both
        // in bounds of the caller-guaranteed regions.
        unsafe {
            let b = *src.add(i);
            *dst.add(i * 2) = b >> 4;
            *dst.add(i * 2 + 1) = b & 0x0f;
        }
    }
}

/// AVX2 expansion: 16 input bytes -> 32 output nibbles per iteration.
///
/// Rather than shuffling the high and low nibbles apart and re-interleaving
/// them, this widens each input byte into its own 16-bit lane and builds the
/// interleaved result with two shifts and an OR. Since x86 is little-endian,
/// a lane holding `(lo << 8) | hi` stores as the byte pair `[hi, lo]` — exactly
/// the output order we want, with no cross-lane permute and no shuffle-control
/// constant to load.
///
/// Per 16 bytes: one load, one widen, two shifts, an AND, an OR, one store.
///
/// # Safety
/// Same contract as [`expand`], plus the CPU must support AVX2.
#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "avx2")]
unsafe fn expand_avx2(src: *const u8, len: usize, dst: *mut u8) {
    // Selects the low nibble after it has been shifted into the lane's high byte.
    let lo_nibble_mask = _mm256_set1_epi16(0x0f00u16 as i16);

    let mut i = 0usize;
    while i + 16 <= len {
        // SAFETY: `i + 16 <= len`, so the 16-byte load at `src + i` is in
        // bounds, and the 32-byte store at `dst + i * 2` fits within the
        // caller-guaranteed `len * 2` bytes.
        unsafe {
            // Zero-extend 16 bytes into 16 u16 lanes: lane = 0x00ab.
            let widened = _mm256_cvtepu8_epi16(_mm_loadu_si128(src.add(i).cast()));

            // 0x00ab >> 4        = 0x000a  -> low byte of lane  = high nibble
            let high_nibbles = _mm256_srli_epi16::<4>(widened);
            // (0x00ab << 8) & m  = 0x0b00  -> high byte of lane = low nibble
            let low_nibbles =
                _mm256_and_si256(_mm256_slli_epi16::<8>(widened), lo_nibble_mask);

            // Lane 0x0b0a stores little-endian as [0x0a, 0x0b].
            let interleaved = _mm256_or_si256(high_nibbles, low_nibbles);
            _mm256_storeu_si256(dst.add(i * 2).cast(), interleaved);
        }
        i += 16;
    }

    // Tail: fewer than 16 bytes left. For 32-byte account hashes this never runs.
    // SAFETY: `i <= len`; the remaining range is in bounds by the caller's contract.
    unsafe { expand_scalar(src.add(i), len - i, dst.add(i * 2)) }
}

